"A booking is confirmed": "訂房已確認",
"Create the invoice and send it to the guest": "建立發票並發給房客",
"Invoice number assigned automatically. Direct bookings get it on WhatsApp, platform bookings by email. Same switch as the invoice settings in Invoices & Receipts.": "發票號碼自動編排。直接訂房經 WhatsApp 發送，平台訂房經電子郵件發送。與「發票與收據」的發票設定為同一開關。",
"Auto": "自動",
"Payment arrives for a booking": "訂房款項已到",
"Create the receipt and send it to the guest": "建立收據並發給房客",
"The receipt is created as soon as the payment is recorded and sent at 6:00 PM that day, on the same channel as the invoice. Same switch as the receipt settings in Invoices & Receipts.": "記錄付款後立即產生收據，並於當天下午 6:00 經與發票相同的管道發送。與「發票與收據」的收據設定為同一開關。",
"Staff record an expense they paid personally": "員工記錄自付的支出",
"Ask the owner to approve the claim": "請擁有者核准報銷",
"The claim stays pending until an account owner approves it. Approval cannot be given to other roles.": "報銷會保持待審，直到帳戶擁有者核准。此核准權無法給其他角色。",
"A booking is made for arrival today": "有今天抵達的訂房",
"Alert the ops manager and create an urgent turnover task": "通知營運經理並建立緊急換房任務",
"If the unit still needs cleaning, the turnover for the property's housekeeper is marked urgent and due 15 minutes before arrival. If it is already clean, a pre-arrival inspection is created instead. The booking shows under Same-day bookings on the dashboard.": "若單位仍需清潔，房源房務員的換房任務會標為緊急，須在抵達前 15 分鐘完成；若已清潔，則建立抵達前檢查。此訂房會顯示在儀表板的「當天訂房」。",
"A guest opens the door code in the guest app": "房客在應用程式中開啟門鎖密碼",
"Show the house rules first and require acceptance": "先顯示入住規則並要求同意",
"The guest ticks agree and types their name. The door code stays hidden until rules are accepted and ID is verified.": "房客勾選同意並輸入姓名。同意規則且證件核實前，門鎖密碼不會顯示。",
"A guest reports damage in the guest app": "房客在應用程式中回報損壞",
"Create a maintenance task with the photos and alert maintenance": "建立附照片的維修任務並通知維修人員",
"Every damaged item needs a photo. The task is assigned to maintenance and linked to the booking for any deposit claim.": "每件損壞物品都需要照片。任務指派給維修人員，並連結到訂房以便申請押金。",
"A guest checks out": "房客退房",
"Create a turnover clean for the property's housekeeper": "為房源房務員建立換房清潔",
"Due 15 minutes before the next check-in, or 3:00 PM if nobody arrives that day.": "須在下一次入住前 15 分鐘完成，若當天無人入住則為下午 3:00。",
"A guest reports a problem in a message": "房客在訊息中回報問題",
"Create a maintenance task and alert the ops manager": "建立維修任務並通知營運經理",
"Picks up words like AC, leak, broken, no water, no hot water, smell.": "偵測如冷氣、漏水、壞了、沒水、沒熱水、異味等字詞。",
