"These came from numbers or booking-site threads that match no booking. Link each to the guest's stay so replies and the stay details sit together.": "這些來自無法對應任何訂房的號碼或訂房網站對話。請連結到房客的住宿，讓回覆與住宿資料在一起。",
"Choose the booking first": "請先選擇訂房",
"On: guest messages, inquiries and reviews from Booking.com, Airbnb and Expedia come into this inbox and the Reviews page, and replies go back to the site.": "已開啟：來自 Booking.com、Airbnb 與 Expedia 的房客訊息、詢問與評價會進入此收件匣與評價頁，回覆會送回網站。",
"Switched on": "已開啟",
"Bring guest messages, inquiries and reviews from Booking.com, Airbnb and Expedia into Orbique, and answer them here. This switches on Channex's Messaging & Reviews app for your connected buildings (Channex bills it to your Channex account: about USD 0.50 per unit a month).": "把 Booking.com、Airbnb 與 Expedia 的房客訊息、詢問與評價帶進 Orbique 並在此回覆。這會為已連接的大樓開啟 Channex 的 Messaging & Reviews 應用程式（由 Channex 向你的帳號收費：每單位每月約 USD 0.50）。",
"Agoda and Trip.com do not offer messages through the channel manager; their emails can come in through your booking email below.": "Agoda 與 Trip.com 不透過通路管理系統提供訊息，其郵件可透過下方的訂房郵件進來。",
"Check again and fetch reviews": "重新檢查並抓取評價",
"Switch on messages and reviews": "開啟訊息與評價",
"Ask the account owner to switch this on.": "請帳戶擁有者開啟。",
"Email is not set up on the server yet. Orbique needs receiving switched on for its email domain in Resend (see Putting Orbique online, Booking email).": "伺服器尚未設定電子郵件。Orbique 需在 Resend 為其郵件網域開啟收信（請見 Putting Orbique online, Booking email）。",
"Every email sent to this address comes into the inbox: guests' emails as chats you can answer, and the booking sites' emails (new bookings, changes, payouts, reviews) as updates on the stay, or under Email & updates.": "寄到此地址的郵件都會進入收件匣：房客郵件成為可回覆的聊天，訂房網站郵件（新訂房、變更、撥款、評價）成為住宿更新，或列在「郵件與通知」。",
"How to set it up:": "設定方式：",
"use one email for all your bookings, for example bookings@yourcompany.com. Give it to Booking.com, Airbnb, Agoda, Trip.com and Expedia as the reservation email. Then, in that mailbox, forward every email to the address above (Gmail: Settings, Forwarding and POP/IMAP, Add a forwarding address; the confirmation email Gmail sends shows up under Email & updates, so you can confirm it from here).": "所有訂房使用同一個信箱，例如 bookings@yourcompany.com，提供給 Booking.com、Airbnb、Agoda、Trip.com 與 Expedia 作為訂房信箱。接著在該信箱把每封郵件轉寄到上方地址（Gmail：Settings、Forwarding and POP/IMAP、Add a forwarding address；Gmail 寄的確認信會出現在「郵件與通知」，可在此確認）。",
"Receiving is not finished on the server yet (RESEND_WEBHOOK_SECRET), so emails do not arrive yet.": "伺服器收信尚未完成設定（RESEND_WEBHOOK_SECRET），郵件暫時收不到。",
"Also on the WhatsApp Business app on your phone. Messages you send from the phone show here as \"From the WhatsApp app\".": "手機上的 WhatsApp Business 應用程式也可使用。從手機發送的訊息會在此顯示為「來自 WhatsApp 應用程式」。",
"The chats of the last 6 months were asked for on": "已要求過去 6 個月的聊天：",
"and come in over the next hours (if you agreed to share them on the phone).": "並會在接下來幾小時內傳入（若你已在手機上同意分享）。",
"WhatsApp did not share the older chats. New messages still come in.": "WhatsApp 未分享舊聊天，新訊息仍會進來。",
"The number was disconnected from Orbique on the phone, so messages no longer come in. Connect it again to carry on.": "此號碼已在手機上與 Orbique 中斷，訊息不再進來。請重新連接。",
"Connect with Facebook again": "重新以 Facebook 連接",
"To stop it fully, also disconnect it on the phone: WhatsApp Business app, Settings, Account, Business Platform.": "若要完全停止，也請在手機上中斷：WhatsApp Business 應用程式 → Settings → Account → Business Platform。",
"Facebook did not load.": "Facebook 未載入。",
"Facebook did not load. Check your connection and try again.": "Facebook 未載入，請檢查網路後再試。",
"Could not load Facebook. Check that nothing blocks connect.facebook.net and try again.": "無法載入 Facebook，請確認沒有封鎖 connect.facebook.net 後再試。",
"The Facebook window was closed. Nothing was connected.": "Facebook 視窗已關閉，未連接任何項目。",
"Facebook reported an error. Nothing was connected.": "Facebook 回報錯誤，未連接任何項目。",
"Facebook did not finish the sign-in. Nothing was connected.": "Facebook 未完成登入，未連接任何項目。",
"For example 109876543210987": "例如 109876543210987",
"Phone number ID from Meta": "Meta 的 Phone number ID",
"Meta for Developers, your app, WhatsApp, API Setup: the \"Phone number ID\" under your business number.": "Meta for Developers → 你的應用程式 → WhatsApp → API Setup：商家號碼下方的「Phone number ID」。",
"Connect by Phone number ID": "以 Phone number ID 連接",
"WhatsApp is not set up on the server yet. Orbique needs WHATSAPP_APP_SECRET and WHATSAPP_VERIFY_TOKEN in Vercel, with WHATSAPP_APP_ID and WHATSAPP_CONFIG_ID to connect with Facebook (see Putting Orbique online, WhatsApp).": "伺服器尚未設定 WhatsApp。Orbique 需要在 Vercel 設定 WHATSAPP_APP_SECRET 與 WHATSAPP_VERIFY_TOKEN，以 Facebook 連接還需 WHATSAPP_APP_ID 與 WHATSAPP_CONFIG_ID（請見 Putting Orbique online, WhatsApp）。",
"Ask the account owner to connect your WhatsApp business number.": "請帳戶擁有者連接你的 WhatsApp 商家號碼。",
"Connect the number you use on the": "連接你使用的號碼：",
"WhatsApp Business app": "WhatsApp Business 應用程式",
". It keeps working on your phone: messages you send from the phone show here too, and the chats of the last 6 months come in once.": "。手機上照常使用：手機發送的訊息也會顯示在這裡，過去 6 個月的聊天會匯入一次。",
"Connect with Facebook": "以 Facebook 連接",
"A Facebook window opens. Choose your business, then \"Connect your existing WhatsApp Business app\", enter the number and confirm on your phone with the QR code the window shows (WhatsApp Business app 2.24.17 or newer). Use a computer browser for this step.": "會開啟 Facebook 視窗。選擇你的商家，再選「Connect your existing WhatsApp Business app」，輸入號碼並用手機掃描視窗中的 QR 碼確認（WhatsApp Business 2.24.17 以上）。此步驟請用電腦瀏覽器。",
"Or connect a number that is only on the Cloud API": "或連接只在 Cloud API 上的號碼",
"Show guest messages in": "房客訊息顯示語言：",
