"sells about {x} of nights. The plans adjust today's prices; they do not work out a market price from scratch.": "約售出 {x} 的夜數。方案只調整今日價格，不會從零推算市場價格。",
"To keep the unit types in this building in order{x}": "為讓此建築的單位類型維持順序{x}",
"and at least {x} apart (or as far apart as today, where that is less)": "且至少相差 {x}（若今天差距較小則維持今天）",
". That limits the prices of {x}": "。這會限制 {x} 的價格",
