"no price in steps of {x} fits between {x}, so there the plans use a single price, the step nearest today's price or halfway, never above the dearer type.": "沒有以 {x} 為級距的價格能介於 {x} 之間，因此在那裡方案使用單一價格，即最接近今日價格或中間值的級距，絕不高於較貴的類型。",
"your lowest price, {x}, leaves no room under {x}, so the plans use it there.": "你的最低價格 {x} 在 {x} 下方沒有空間，因此方案在那裡使用它。",
"the lowest price tried ({x} leaves no room under {x}, so the plans use it there.": "嘗試的最低價格（{x} 在 {x} 下方沒有空間，因此方案在那裡使用它。",
"your highest price, {x}, leaves no room over {x}, so the plans use it there.": "你的最高價格 {x} 在 {x} 上方沒有空間，因此方案在那裡使用它。",
"the highest price tried ({x} leaves no room over {x}, so the plans use it there.": "嘗試的最高價格（{x} 在 {x} 上方沒有空間，因此方案在那裡使用它。",
