"Guests book late for these dates: {x} of the nights likely to sell usually book in the last {x} days before arrival, so the calendar fills late.": "這些日期的房客較晚預訂：可能售出的夜數中有 {x} 通常在抵達前最後 {x} 天內預訂，因此行事曆較晚才會滿。",
"On average, no plan reaches {x} a month. The best one {x}": "平均而言，沒有方案能達到每月 {x}。最好的方案 {x}",
