"On average, no plan covers all costs in these dates. The best one loses about {x} a month.": "平均而言，在這些日期沒有方案能涵蓋所有成本。最好的方案每月約虧損 {x}。",
", costs would need to be about {x} a month lower{x}": "，成本每月需降低約 {x}{x}",
